/**
 * @publicApi
 */
export class NatsRecord {
    data;
    headers;
    constructor(data, headers) {
        this.data = data;
        this.headers = headers;
    }
}
/**
 * @publicApi
 */
export class NatsRecordBuilder {
    data;
    headers;
    constructor(data) {
        this.data = data;
    }
    setHeaders(headers) {
        this.headers = headers;
        return this;
    }
    setData(data) {
        this.data = data;
        return this;
    }
    build() {
        return new NatsRecord(this.data, this.headers);
    }
}
